js='''(()=>{const items=ITEMS,bykey=Object.fromEntries(items.map(x=>[x.key,x])),q=id=>document.getElementById('popup-'+id),base='popup-profile-v1-20261020/',widths={'4x3':960,'16x10':1152,'16x9':1280,'21x9':1680,'32x9':2560};function stage(){let it=bykey[q('item').value],a=q('aspect').value,w=widths[a];q('stage-original').src=base+it.key+'-'+a+'-original.png';q('stage-draft').src=base+it.key+'-'+a+(it.key==='profile-wall'?(q('wall-revision').value==='v1'?'-draft.png':'-draft-'+q('wall-revision').value+'.png'):'-draft.png');q('stage-pair').dataset.bg=q('bg').value;for(let e of document.querySelectorAll('.popup-safe'))Object.assign(e.style,{width:(960/w*100)+'%',left:((w-960)/2/w*100)+'%'});q('stage-caption').textContent=it.label+' · '+a.replace('x',':')+(it.key==='profile-wall'?' · centered original4:3andwidenedwall · study,notgamecapture':' · isolatedsource-shapefootprint,notin-gameplacement');}function update(){let it=bykey[q('item').value],alpha=q('channel').value==='alpha',orig=alpha?it.alpha_reference_file:(q('ref').value==='faithful'?it.faithful_file:it.source_file),draft=alpha?it.alpha_draft_file:it.draft_file;for(let id of ['original','wipe-original'])q(id).src=base+orig;for(let id of ['draft','wipe-draft'])q(id).src=base+draft;q('original-link').href=base+orig;q('draft-link').href=base+draft;q('mask-link').hidden=!it.mask_file;q('mask-link').href=it.mask_file?base+it.mask_file:base+draft;q('ref-label').textContent=alpha?'Source alpha ·4× coverage':q('ref').selectedOptions[0].textContent;q('method').textContent=it.method;q('caption').textContent=it.label+' · '+it.native_size.join('×')+'native →4× · source alpha/geometry/graphics protected · UNAPPROVED · '+it.placement;q('comparison').dataset.bg=q('bg').value;q('comparison').dataset.view=q('view').value;q('wipe-controls').hidden=q('view').value!=='wipe';q('wipe-draft').style.clipPath='inset(0 0 0 '+q('wipe').value+'%)';q('joins').hidden=it.key!=='profile-wall';let raw=it.raw_file;q('raw').hidden=!raw;if(raw)q('raw-image').src=base+raw;else q('raw-image').removeAttribute('src');stage();}for(let id of ['item','ref','channel','bg','view'])q(id).onchange=update;q('aspect').onchange=stage;q('wall-revision').onchange=stage;q('wipe').oninput=update;q('bounds').onclick=()=>{let v=q('bounds').getAttribute('aria-pressed')!=='true';q('bounds').setAttribute('aria-pressed',String(v));for(let e of document.querySelectorAll('.popup-stage-frame'))e.classList.toggle('show',v);};update();})();'''.replace('ITEMS',json.dumps(items,ensure_ascii=False).replace('</','<\\/'))
